const utcDay=(date:string)=>Date.parse(date+'T00:00:00Z');
function bindPointTooltips(selector:string){const container=$(selector),points=container.querySelectorAll<SVGElement>('[data-point-label]');if(!points.length)return;const tip=document.createElement('div');tip.className='chart-tooltip';tip.setAttribute('role','status');tip.hidden=true;container.appendChild(tip);let pinned:SVGElement|null=null;const show=(point:SVGElement)=>{const box=point.getBoundingClientRect(),host=container.getBoundingClientRect();tip.textContent=point.dataset.pointLabel||'';tip.style.left=`${Math.max(68,Math.min(host.width-68,box.left-host.left+box.width/2))}px`;tip.style.top=`${Math.max(8,box.top-host.top-8)}px`;tip.hidden=false;};const hide=()=>{if(!pinned)tip.hidden=true;};points.forEach(point=>{point.addEventListener('mouseenter',()=>show(point));point.addEventListener('mouseleave',hide);point.addEventListener('focus',()=>show(point));point.addEventListener('blur',hide);point.addEventListener('click',event=>{event.stopPropagation();pinned=pinned===point?null:point;if(pinned)show(point);else tip.hidden=true;});});container.addEventListener('click',event=>{if(!(event.target as Element).closest('[data-point-label]')){pinned=null;tip.hidden=true;}});}
function applyProgressHighlight(series:'actual'|'plan'|null){document.querySelectorAll<HTMLElement>('[data-progress-series],[data-progress]').forEach(e=>{const own=(e.dataset.progressSeries||e.dataset.progress) as 'actual'|'plan'|undefined;e.classList.toggle('series-highlighted',!!series&&own===series);e.classList.toggle('series-muted',!!series&&own!==series);if(e.matches('button'))e.setAttribute('aria-pressed',String(selectedProgress===own));});}
function renderProgress(){
  const history=[...portfolio.history].sort((a,b)=>a.date.localeCompare(b.date));
  if(!history.length)return;
  const baseline=currentPlanBaseline(history)!;
  const stageHistory=history.filter(point=>point.date>=baseline.baseDate),latest=stageHistory.at(-1)!;
  const plannedNow=baseline.target,annualGoal=plannedValue(baseline.baseValue,365),ahead=latest.total-plannedNow;
  $('#progress-summary').innerHTML=`<article><span>最新实际</span><strong>${money(latest.total)}</strong><small>${latest.date}</small></article><article><span>当前计划本金</span><strong>${money(baseline.baseValue)}</strong><small>${baseline.baseDate} 重新起算</small></article><article><span>同期 10% 计划</span><strong>${money(plannedNow)}</strong><small>一年目标 ${money(annualGoal)}</small></article><article><span>领先 / 落后计划</span><strong class="${ahead<0?'negative':ahead>0?'positive':''}">${ahead>=0?'+':''}${money(ahead)}</strong><small>最新结算盈亏 ${latest.settledPnl===undefined?'—':`${latest.settledPnl>=0?'+':''}${money(latest.settledPnl)}`}</small></article>`;

  const dayMs=86400000,baseStart=utcDay(baseline.baseDate),maxTimelineDays=365;
  progressWindowDays=Math.max(5,Math.min(maxTimelineDays,progressWindowDays));
  progressOffsetDays=Math.max(0,Math.min(maxTimelineDays-progressWindowDays,progressOffsetDays));
  const visibleStart=baseStart+progressOffsetDays*dayMs,visibleEnd=visibleStart+progressWindowDays*dayMs;
  const isoAt=(day:number)=>new Date(baseStart+day*dayMs).toISOString().slice(0,10);
  const visibleActual=stageHistory.filter(point=>{const time=utcDay(point.date);return time>=visibleStart&&time<=visibleEnd;});
  const sampleCount=Math.max(30,Math.min(180,Math.ceil(progressWindowDays*2)));
  const planSamples=Array.from({length:sampleCount+1},(_,index)=>{const day=progressOffsetDays+progressWindowDays*index/sampleCount;return {day,date:isoAt(day),total:plannedValue(baseline.baseValue,day)};});
  const planAtActual=visibleActual.map(point=>{const day=(utcDay(point.date)-baseStart)/dayMs;return {...point,day,plan:plannedValue(baseline.baseValue,day)};});
  const values=[...planSamples.map(point=>point.total),...visibleActual.map(point=>point.total)];
  const lo=Math.min(...values),hi=Math.max(...values),span=Math.max(hi-lo,baseline.baseValue*.004,60),min=lo-span*.2,max=hi+span*.2;
  const xDay=(day:number)=>78+(day-progressOffsetDays)/progressWindowDays*810;
  const xDate=(date:string)=>xDay((utcDay(date)-baseStart)/dayMs);
  const y=(amount:number)=>202-(amount-min)/(max-min)*166;
  const planPath=planSamples.map((point,index)=>`${index?'L':'M'}${xDay(point.day)} ${y(point.total)}`).join(' ');
  const actualPath=visibleActual.map((point,index)=>`${index?'L':'M'}${xDate(point.date)} ${y(point.total)}`).join(' ');
  const areaPath=visibleActual.length>1?`${actualPath} L${xDate(visibleActual.at(-1)!.date)} 202 L${xDate(visibleActual[0].date)} 202 Z`:'';
  const yTicks=Array.from({length:4},(_,index)=>min+(max-min)*index/3);
  const xTicks=Array.from({length:6},(_,index)=>progressOffsetDays+progressWindowDays*index/5);
  const dateLabel=(day:number)=>new Intl.DateTimeFormat('zh-CN',{month:'numeric',day:'numeric',timeZone:'UTC'}).format(new Date(baseStart+day*dayMs));
  const latestDay=(utcDay(latest.date)-baseStart)/dayMs,latestVisible=latestDay>=progressOffsetDays&&latestDay<=progressOffsetDays+progressWindowDays;
  $('#progress-chart').innerHTML=`<div class="market-chart-shell"><div class="market-chart-status"><span>${isoAt(progressOffsetDays)} — ${isoAt(progressOffsetDays+progressWindowDays)}</span><small>可见 ${Math.round(progressWindowDays)} 天 · 滚轮缩放 · 左右拖动</small></div><svg viewBox="0 0 960 245" role="img" aria-label="从 ${baseline.baseDate} 起的总资产与年化 10% 计划对比，可缩放和平移时间轴"><defs><linearGradient id="progress-area" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#3c5fea" stop-opacity=".18"/><stop offset="100%" stop-color="#3c5fea" stop-opacity=".01"/></linearGradient><clipPath id="progress-clip"><rect x="78" y="23" width="810" height="179"/></clipPath></defs><rect x="78" y="23" width="810" height="179" class="progress-plot-bg"/>${yTicks.map(value=>`<line x1="78" x2="888" y1="${y(value)}" y2="${y(value)}" class="return-grid"/><text x="8" y="${y(value)+4}" class="axis">${money(value,0)}</text>`).join('')}${xTicks.map((day,index)=>`<line x1="${xDay(day)}" x2="${xDay(day)}" y1="23" y2="202" class="progress-time-grid"/><text x="${xDay(day)}" y="232" text-anchor="${index===0?'start':index===xTicks.length-1?'end':'middle'}" class="axis">${dateLabel(day)}</text>`).join('')}<g clip-path="url(#progress-clip)">${areaPath?`<path d="${areaPath}" class="progress-area"/>`:''}<g class="progress-series" data-progress-series="plan"><path d="${planPath}" class="progress-plan"/><path d="${planPath}" class="progress-hit"/>${planAtActual.map(point=>`<circle cx="${xDay(point.day)}" cy="${y(point.plan)}" r="4" tabindex="0" role="button" class="progress-plan-point"><title>10% 计划 · ${point.date} · ${money(point.plan)}</title></circle>`).join('')}</g><g class="progress-series" data-progress-series="actual">${actualPath.includes('L')?`<path d="${actualPath}" class="progress-actual"/><path d="${actualPath}" class="progress-hit"/>`:''}${visibleActual.map(point=>`<circle cx="${xDate(point.date)}" cy="${y(point.total)}" r="5" tabindex="0" role="button" class="progress-actual-point"><title>每日实际 · ${point.date} · ${money(point.total)}</title></circle>`).join('')}</g>${latestVisible?`<line x1="${xDay(latestDay)}" x2="${xDay(latestDay)}" y1="23" y2="202" class="progress-latest"/>`:''}<g class="progress-crosshair" data-progress-crosshair visibility="hidden"><line data-cross-x x1="78" x2="78" y1="23" y2="202"/><circle data-cross-plan cx="78" cy="23" r="5"/><circle data-cross-actual cx="78" cy="23" r="6" visibility="hidden"/></g></g></svg><div class="market-tooltip" role="status" hidden></div></div>`;

  document.querySelectorAll<HTMLElement>('[data-progress-series]').forEach(group=>{const own=group.dataset.progressSeries as 'actual'|'plan';group.onmouseenter=()=>applyProgressHighlight(own);group.onmouseleave=()=>applyProgressHighlight(selectedProgress);group.querySelectorAll<SVGElement>('.progress-hit,.progress-actual,.progress-plan').forEach(line=>line.onclick=event=>{event.stopPropagation();selectedProgress=selectedProgress===own?null:own;applyProgressHighlight(selectedProgress);});});
  document.querySelectorAll<HTMLButtonElement>('[data-progress]').forEach(button=>{const own=button.dataset.progress as 'actual'|'plan';button.onmouseenter=()=>applyProgressHighlight(own);button.onmouseleave=()=>applyProgressHighlight(selectedProgress);button.onclick=()=>{selectedProgress=selectedProgress===own?null:own;applyProgressHighlight(selectedProgress);};});
  document.querySelectorAll<HTMLButtonElement>('[data-progress-range]').forEach(button=>{const days=Number(button.dataset.progressRange);button.setAttribute('aria-pressed',String(progressWindowDays===days&&progressOffsetDays===0));button.onclick=()=>{progressWindowDays=days;progressOffsetDays=0;renderProgress();};});
  const zoom=(factor:number,anchor=.5)=>{const oldWindow=progressWindowDays,newWindow=Math.max(5,Math.min(maxTimelineDays,Math.round(oldWindow*factor)));const anchorDay=progressOffsetDays+oldWindow*anchor;progressWindowDays=newWindow;progressOffsetDays=Math.max(0,Math.min(maxTimelineDays-newWindow,anchorDay-newWindow*anchor));renderProgress();};
  $('#progress-zoom-in').addEventListener('click',()=>zoom(.7));
  $('#progress-zoom-out').addEventListener('click',()=>zoom(1.4));
  $('#progress-fit').addEventListener('click',()=>{progressWindowDays=30;progressOffsetDays=0;renderProgress();});
  const shell=$<HTMLElement>('#progress-chart .market-chart-shell'),svg=$<SVGSVGElement>('#progress-chart svg'),cross=$<SVGGElement>('[data-progress-crosshair]'),tooltip=$<HTMLElement>('#progress-chart .market-tooltip');
  const crossLine=cross.querySelector<SVGLineElement>('[data-cross-x]')!,crossPlan=cross.querySelector<SVGCircleElement>('[data-cross-plan]')!,crossActual=cross.querySelector<SVGCircleElement>('[data-cross-actual]')!;
  let dragStart:number|null=null,dragOffset=0,dragged=false;
  const chartX=(clientX:number)=>{const rect=svg.getBoundingClientRect();return Math.max(78,Math.min(888,(clientX-rect.left)/rect.width*960));};
  const showCrosshair=(event:PointerEvent)=>{if(dragStart!==null)return;const vx=chartX(event.clientX),day=progressOffsetDays+(vx-78)/810*progressWindowDays,date=isoAt(day),plan=plannedValue(baseline.baseValue,day),nearest=stageHistory.map(point=>({point,diff:Math.abs((utcDay(point.date)-baseStart)/dayMs-day)})).sort((a,b)=>a.diff-b.diff)[0],actual=nearest&&nearest.diff<=.55?nearest.point:null;cross.setAttribute('visibility','visible');crossLine.setAttribute('x1',String(vx));crossLine.setAttribute('x2',String(vx));crossPlan.setAttribute('cx',String(vx));crossPlan.setAttribute('cy',String(y(plan)));if(actual){crossActual.setAttribute('visibility','visible');crossActual.setAttribute('cx',String(xDate(actual.date)));crossActual.setAttribute('cy',String(y(actual.total)));}else crossActual.setAttribute('visibility','hidden');const rect=shell.getBoundingClientRect();tooltip.innerHTML=`<strong>${date}</strong><span><i class="actual-dot"></i>实际 ${actual?money(actual.total):'—'}</span><span><i class="plan-dot"></i>10% 计划 ${money(plan)}</span>`;tooltip.style.left=`${Math.max(86,Math.min(rect.width-86,event.clientX-rect.left))}px`;tooltip.style.top=`${Math.max(40,event.clientY-rect.top-14)}px`;tooltip.hidden=false;};
  svg.addEventListener('pointermove',event=>{if(dragStart!==null){dragged=Math.abs(event.clientX-dragStart)>4;svg.classList.toggle('is-panning',dragged);return;}showCrosshair(event);});
  svg.addEventListener('pointerleave',()=>{if(dragStart===null){cross.setAttribute('visibility','hidden');tooltip.hidden=true;}});
  svg.addEventListener('pointerdown',event=>{if(event.button!==0||(event.target as Element).closest('.progress-series'))return;dragStart=event.clientX;dragOffset=progressOffsetDays;dragged=false;svg.setPointerCapture(event.pointerId);svg.classList.add('is-grabbing');});
  const finishDrag=(event:PointerEvent)=>{if(dragStart===null)return;const rect=svg.getBoundingClientRect(),delta=(dragStart-event.clientX)/rect.width*960/810*progressWindowDays;svg.classList.remove('is-grabbing','is-panning');dragStart=null;if(dragged){progressOffsetDays=Math.max(0,Math.min(maxTimelineDays-progressWindowDays,dragOffset+delta));renderProgress();}};
  svg.addEventListener('pointerup',finishDrag);svg.addEventListener('pointercancel',finishDrag);
  shell.addEventListener('wheel',event=>{event.preventDefault();const rect=svg.getBoundingClientRect(),viewX=(event.clientX-rect.left)/rect.width*960,anchor=Math.max(0,Math.min(1,(viewX-78)/810));zoom(event.deltaY>0?1.18:.84,anchor);},{passive:false});
  svg.addEventListener('dblclick',()=>{progressWindowDays=30;progressOffsetDays=0;renderProgress();});
  applyProgressHighlight(selectedProgress);
}

function renderInsights(){const t=totals(portfolio),voo=value(portfolio.holdings.find(h=>h.ticker==='VOO')!),stocks=portfolio.holdings.filter(h=>h.kind==='个股').sort((a,b)=>value(b)-value(a)),largest=stocks[0];
  $('#insights').innerHTML=`<article class="insight"><span class="insight-number">01 / 核心配置</span><h3>VOO 占证券 ${pct(voo,t.securities)}</h3><p>占全账户 ${pct(voo,t.total)}。判断是否接近原先 80% 的目标，需要先固定分母；一张饼图换了口径，比例也会改变。</p></article><article class="insight"><span class="insight-number">02 / 单股集中度</span><h3>${largest.ticker} 是最大的单股持仓</h3><p>占证券 ${pct(value(largest),t.securities)}，占全账户 ${pct(value(largest),t.total)}。它就像组合里较重的一块积木，股价波动对整体影响更大。</p></article><article class="insight"><span class="insight-number">03 / 现金缓冲</span><h3>${pct(t.cash,t.total)} 处于现金及其他</h3><p>现金估算会缓冲股票下跌，也减少上涨时的参与度。ETF 与科技个股存在重叠；增加代码数量不必然增加分散程度。</p></article>`;
}
type ReturnSeries={ticker:string;color:string,points:{date:string,value:number}[]};
function returnChartSvg(series:ReturnSeries[],label:string,scope:'account'|'stock'){const dates=marketHistory.map(point=>point.date),values=series.flatMap(line=>line.points.map(point=>point.value));const low=Math.min(0,...values),high=Math.max(0,...values),rawSpan=Math.max(high-low,1),min=low-rawSpan*.18,max=high+rawSpan*.18;const x=(date:string)=>dates.length<=1?480:72+dates.indexOf(date)/(dates.length-1)*820;const y=(v:number)=>214-(v-min)/(max-min)*174;const ticks=[min,(min+max)/2,max];
  const lines=series.map(line=>{const d=line.points.map((point,i)=>`${i?'L':'M'}${x(point.date)} ${y(point.value)}`).join(' '),latest=line.points[line.points.length-1];return `<g class="return-series" data-return-scope="${scope}" data-return="${line.ticker}" style="--line:${line.color}">${line.points.length>1?`<path class="return-line" d="${d}"/><path class="return-hit" d="${d}"/>`:`<circle class="return-hit-point" cx="${x(latest?.date||dates[0])}" cy="${y(latest?.value||0)}" r="13"/>`}${line.points.map(point=>`<circle class="return-point" cx="${x(point.date)}" cy="${y(point.value)}" r="4" tabindex="0" role="button" data-point-label="${esc(`${line.ticker} · ${point.date} · ${point.value>=0?'+':''}${point.value.toFixed(2)}%`)}"/>`).join('')}</g>`;}).join('');
  return `<svg viewBox="0 0 960 255" role="img" aria-label="${label}">${ticks.map(n=>`<line x1="72" x2="892" y1="${y(n)}" y2="${y(n)}" class="return-grid"/><text x="8" y="${y(n)+4}" class="axis">${n>=0?'+':''}${n.toFixed(1)}%</text>`).join('')}<line x1="72" x2="892" y1="${y(0)}" y2="${y(0)}" class="return-zero"/>${lines}<text x="72" y="245" class="axis">${dates[0]||''}</text>${dates.length>1?`<text x="892" y="245" text-anchor="end" class="axis">${dates[dates.length-1]}</text>`:''}</svg>${dates.length<2?'<p class="return-empty">目前只有起始收盘点。下一交易日更新后，曲线会开始延伸。</p>':''}`;
}
function applyReturnHighlight(scope:'account'|'stock',ticker:string|null){document.querySelectorAll<HTMLElement>(`[data-return-scope="${scope}"]`).forEach(e=>{e.classList.toggle('highlighted',!!ticker&&e.dataset.return===ticker);e.classList.toggle('muted-line',!!ticker&&e.dataset.return!==ticker);if(e.matches('button'))e.setAttribute('aria-current',ticker===e.dataset.return?'true':'false');});}
function bindReturnSeries(scope:'account'|'stock'){const locked=()=>scope==='account'?(selectedAccount?'账户':null):selectedReturnTicker;document.querySelectorAll<HTMLElement>(`.return-series[data-return-scope="${scope}"]`).forEach(e=>{const ticker=e.dataset.return!;e.onmouseenter=()=>applyReturnHighlight(scope,ticker);e.onfocus=()=>applyReturnHighlight(scope,ticker);e.onmouseleave=()=>applyReturnHighlight(scope,locked());e.onblur=()=>applyReturnHighlight(scope,locked());e.querySelectorAll<SVGElement>('.return-hit,.return-line,.return-hit-point').forEach(line=>line.onclick=event=>{event.stopPropagation();if(scope==='account')selectedAccount=!selectedAccount;else selectedReturnTicker=selectedReturnTicker===ticker?null:ticker;applyReturnHighlight(scope,locked());});});applyReturnHighlight(scope,locked());}
